 s+='<path d="M-10 70 Q50 30 100 60 T210 50" stroke="#3DFFB0" stroke-width="22" fill="none" opacity=".45"/><path d="M-10 95 Q60 60 110 88 T210 78" stroke="#00D9FF" stroke-width="16" fill="none" opacity=".4"/><path d="M-10 115 Q70 90 120 110 T210 100" stroke="#8FB8FF" stroke-width="10" fill="none" opacity=".35"/><path d="M0 200 L0 160 L30 140 L60 165 L95 135 L130 160 L165 138 L200 158 L200 200Z" fill="#030914"/>';o.aurora=s;
